from itertools import product
import heapq
from collections import Counter


def dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        order = names if name_order == "ascending" else names[::-1]
        rows = {name: {r["version"]: r for r in versions}
                for name, versions in packages.items()}
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = [[-1] + sorted(rows[n]) for n in names]
        best = None
        best_vector = None
        for vals in product(*choices):
            selected = dict(zip(names, vals))
            installed = {n for n, v in selected.items() if v != -1}
            if any(n not in installed for n in data["roots"]):
                continue
            if any(v in blocked.get(n, []) or (n in pins and pins[n] != v)
                   for n, v in selected.items() if v != -1):
                continue
            limits = {n: list(bounds) for n, bounds in data["roots"].items()}
            reached = set()
            edges = {}
            pending = list(data["roots"])
            valid = True
            while pending and valid:
                name = pending.pop()
                if name in reached:
                    continue
                reached.add(name)
                version = selected[name]
                if version == -1 or name not in limits or not limits[name][0] <= version <= limits[name][1]:
                    valid = False
                    break
                deps = []
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    deps.append(other)
                    if other in limits:
                        limits[other][0] = max(limits[other][0], dep["min"])
                        limits[other][1] = min(limits[other][1], dep["max"])
                    else:
                        limits[other] = [dep["min"], dep["max"]]
                    if limits[other][0] > limits[other][1]:
                        valid = False
                        break
                    pending.append(other)
                edges[name] = deps
            if not valid or reached != installed:
                continue
            state = {}
            def visit(node):
                if state.get(node) == 1:
                    return False
                if state.get(node) == 2:
                    return True
                state[node] = 1
                if any(not visit(child) for child in edges.get(node, [])):
                    return False
                state[node] = 2
                return True
            if any(not visit(n) for n in reached):
                continue
            vector = tuple(selected[n] for n in order)
            if best is None or ((vector > best_vector) if preference == "maximum" else (vector < best_vector)):
                best, best_vector = {n: selected[n] for n in installed}, vector
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def component_06(data):
    def rounded(n, d, mode):
        return n // d if mode == "floor" else (2 * n + d) // (2 * d)
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        eid = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if eid not in chosen or key > chosen[eid][0]:
            chosen[eid] = (key, event)
    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, data["rounding"])
        tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def component_07(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_ids = None
    best_value = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = sorted(j["id"] for j in chosen)
        idset = set(ids)
        if idset & blocked or not mandatory <= idset:
            continue
        counts = Counter(j["group"] for j in chosen)
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        active = []
        good = True
        for job in sorted(chosen, key=lambda j: (j["start"], j["end"], j["id"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                good = False
                break
        if not good:
            continue
        value = sum(j["value"] for j in chosen)
        if best_ids is None or value > best_value or (value == best_value and ids < best_ids):
            best_ids, best_value = ids, value
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def component_08(data):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bits.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if time != dist.get(state):
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bits.get(nxt, 0)
                next_state = (nxt, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


SOLVERS = {
    "component_01": dependency_solver("maximum", "ascending"),
    "component_02": dependency_solver("minimum", "ascending"),
    "component_03": dependency_solver("maximum", "descending"),
    "component_04": dependency_solver("minimum", "descending"),
    "component_05": dependency_solver("maximum", "ascending"),
    "component_06": component_06,
    "component_07": component_07,
    "component_08": component_08,
}

